+/// Lowest steel above the tip at horizontal distance `d <= r`.
+fn lift(k: Kind, d: f64, r: f64) -> f64 {
+    match k {
+        Kind::Flat => 0.0,
+        Kind::Ball => r - (r * r - d * d).max(0.0).sqrt(),
+        Kind::Cone(cot) => cot * d,
+        Kind::Bull(c) => {
+            let e = (d - (r - c)).max(0.0);
+            c - (c * c - e * e).max(0.0).sqrt()
+        }
+    }
