+fn arc(ox: f64, oy: f64, rad: f64, a0: f64, sweep: f64, z0: f64, z1: f64) -> Move {
+    let a1 = a0 + sweep;
+    Move {
+        rotary: None,
+        kind: MoveKind::Feed,
+        from: Point3::new(ox + rad * a0.cos(), oy + rad * a0.sin(), z0),
+        to: Point3::new(ox + rad * a1.cos(), oy + rad * a1.sin(), z1),
+        feed: Some(500.0),
